"""
AgentShield AI — Security Decision Database Model (Phase 4).
"""

from __future__ import annotations

from datetime import datetime

from sqlalchemy import Boolean, DateTime, Float, ForeignKey, Index, Integer, String, Text
from sqlalchemy.orm import Mapped, mapped_column

from agentshield.database.base import Base, UUIDPrimaryKeyMixin, utc_now


class SecurityDecisionModel(Base, UUIDPrimaryKeyMixin):
    """Persisted security authorization decision generated by AgentShield."""

    __tablename__ = "security_decisions"

    request_id: Mapped[str] = mapped_column(
        String(36),
        index=True,
        nullable=False,
    )
    user_id: Mapped[str] = mapped_column(
        String(36),
        ForeignKey("users.id", ondelete="CASCADE"),
        index=True,
        nullable=False,
    )
    agent_id: Mapped[str] = mapped_column(
        String(36),
        index=True,
        nullable=False,
    )
    decision: Mapped[str] = mapped_column(
        String(32),
        index=True,
        nullable=False,
    )
    risk_score: Mapped[float] = mapped_column(
        Float,
        default=0.0,
        nullable=False,
    )
    risk_level: Mapped[str] = mapped_column(
        String(32),
        index=True,
        nullable=False,
    )
    reasons_json: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
    )
    matched_policy_ids_json: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
    )
    policy_version: Mapped[int] = mapped_column(
        Integer,
        default=1,
        nullable=False,
    )
    approval_required: Mapped[bool] = mapped_column(
        Boolean,
        default=False,
        nullable=False,
    )
    approval_id: Mapped[str | None] = mapped_column(
        String(36),
        nullable=True,
    )
    evaluation_duration_ms: Mapped[float | None] = mapped_column(
        Float,
        nullable=True,
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        default=utc_now,
        nullable=False,
        index=True,
    )

    __table_args__ = (
        Index("ix_decision_user_created", "user_id", "created_at"),
        Index("ix_decision_user_decision", "user_id", "decision"),
    )
